        if (r.code === 'daily_limit' && typeof r.body.plans_left === 'number') setPlansLeft(r.body.plans_left) // KINEO-ADS-FIEL-2-1510
        setPlanError(failText(r)) // KINEO-BUSINESS-POS-AMOSTRA-2026-10-12
