      setPlansLeft(typeof r.data.plans_left === 'number' ? r.data.plans_left : null) // KINEO-ADS-FIEL-2-1510
      setPlan({ ...r.data, sig: JSON.stringify({ base: baseAtStart, facts: chosen }), cardSig: card.sig })
